    # ---------- 84. 济上四贤咏·郑霍二山人（一作寄崔郑二山人） ----------
    {
        "id": "wang-wei-84",
        "title": "济上四贤咏·郑霍二山人（一作寄崔郑二山人）",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷74》",
        "verse": [
            "翩翩繁华子，多出金张门。幸有先人业，早蒙明主恩。",
            "童年且未学，肉食骛华轩。岂乏中林士，无人荐至尊。",
            "郑公老泉石，霍子安丘樊。卖药不二价，著书盈万言。",
            "息阴无恶木，饮水必清源。吾贱不及议，斯人竟谁论。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 85. 过太乙观贾生房 ----------
    {
        "id": "wang-wei-85",
        "title": "过太乙观贾生房",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷75》",
        "verse": [
            "昔余栖遁日，之子烟霞邻。共携松叶酒，俱篸竹皮巾。",
            "攀林遍岩洞，采药无冬春。谬以道门子，征为骖御臣。",
            "常恐丹液就，先我紫阳宾。夭促万涂尽，哀伤百虑新。",
            "迹峻不容俗，才多反累真。泣对双泉水，还山无主人。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 86. 燕子龛禅师 ----------
    {
        "id": "wang-wei-86",
        "title": "燕子龛禅师",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷76》",
        "verse": [
            "山中燕子龛，路剧羊肠恶。裂地竞盘屈，插天多峭崿。",
            "瀑泉吼而喷，怪石看欲落。伯禹访未知，五丁愁不凿。",
            "上人无生缘，生长居紫阁。六时自搥磬，一饮常带索。",
            "种田烧白云，斫漆响丹壑。行随拾栗猿，归对巢松鹤。",
            "时许山神请，偶逢洞仙博。救世多慈悲，即心无行作。",
            "周商倦积阻，蜀物多淹泊。岩腹乍旁穿，涧唇时外拓。",
            "桥因倒树架，栅值垂藤缚。鸟道悉已平，龙宫为之涸。",
            "跳波谁揭厉，绝壁免扪摸。山木日阴阴，结跏归旧林。",
            "一向石门里，任君春草深。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 87. 羽林骑闺人 ----------
    {
        "id": "wang-wei-87",
        "title": "羽林骑闺人",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷77》",
        "verse": [
            "秋月临高城，城中管弦思。离人堂上愁，稚子阶前戏。",
            "出门复映户，望望青丝骑。行人过欲尽，狂夫终不至。",
            "左右寂无言，相看共垂泪。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 88. 偶然作六首 ----------
    {
        "id": "wang-wei-88",
        "title": "偶然作六首",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷78》",
        "verse": [
            "楚国有狂夫，茫然无心想。散发不冠带，行歌南陌上。",
            "孔丘与之言，仁义莫能奖。未尝肯问天，何事须击壤。",
            "复笑采薇人，胡为乃长往。",
            "田舍有老翁，垂白衡门里。有时农事闲，斗酒呼邻里。",
            "喧聒茅檐下，或坐或复起。短褐不为薄，园葵固足美。",
            "动则长子孙，不曾向城市。五帝与三王，古来称天子。",
            "干戈将揖让，毕竟何者是。得意苟为乐，野田安足鄙。",
            "且当放怀去，行行没馀齿。",
            "日夕见太行，沉吟未能去。问君何以然，世网婴我故。",
            "小妹日成长，兄弟未有娶。家贫禄既薄，储蓄非有素。",
            "几回欲奋飞，踟蹰复相顾。孙登长啸台，松竹有遗处。",
            "相去讵几许，故人在中路。爱染日已薄，禅寂日已固。",
            "忽乎吾将行，宁俟岁云暮。",
            "陶潜任天真，其性颇耽酒。自从弃官来，家贫不能有。",
            "九月九日时，菊花空满手。中心窃自思，傥有人送否。",
            "白衣携壶觞，果来遗老叟。且喜得斟酌，安问升与斗。",
            "奋衣野田中，今日嗟无负。兀傲迷东西，蓑笠不能守。",
            "倾倒强行行，酣歌归五柳。生事不曾问，肯愧家中妇。",
            "赵女弹箜篌，复能邯郸舞。夫婿轻薄儿，斗鸡事齐主。",
            "黄金买歌笑，用钱不复数。许史相经过，高门盈四牡。",
            "客舍有儒生，昂藏出邹鲁。读书三十年，腰间无尺组。",
            "被服圣人教，一生自穷苦。",
            "老来懒赋诗，惟有老相随。宿世谬词客，前身应画师。",
            "不能舍余习，偶被世人知。名字本皆是，此心还不知。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 89. 寓言二首（次首《律髓》入侠少类，作卢象《杂诗》） ----------
    {
        "id": "wang-wei-89",
        "title": "寓言二首（次首《律髓》入侠少类，作卢象《杂诗》）",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷79》",
        "verse": [
            "朱绂谁家子，无乃金张孙。骊驹从白马，出入铜龙门。",
            "问尔何功德，多承明主恩。斗鸡平乐馆，射雉上林园。",
            "曲陌车骑盛，高堂珠翠繁。奈何轩冕贵，不与布衣言。",
            "君家御沟上，垂柳夹朱门。列鼎会中贵，鸣珂朝至尊。",
            "生死在八议，穷达由一言。须识苦寒士，莫矜狐白温。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
