    # ---------- 117. 同比部杨员外十五夜游有怀静者季 ----------
    {
        "id": "wang-wei-117",
        "title": "同比部杨员外十五夜游有怀静者季",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷107》",
        "verse": [
            "承明少休沐，建礼省文书。夜漏行人息，归鞍落日馀。",
            "悬知三五夕，万户千门辟。夜出曙翻归，倾城满南陌。",
            "陌头驰骋尽繁华，王孙公子五侯家。由来月明如白日，",
            "共道春灯胜百花。聊看侍中千宝骑，强识小妇七香车。",
            "香车宝马共喧阗，个里多情侠少年。竞向长杨柳市北，",
            "肯过精舍竹林前。独有仙郎心寂寞，却将宴坐为行乐。",
            "傥觉忘怀共往来，幸沾同舍甘藜藿。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
