    # ---------- 125. 送友人归山歌二首（离骚题作山中人） ----------
    {
        "id": "wang-wei-125",
        "title": "送友人归山歌二首（离骚题作山中人）",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷115》",
        "verse": [
            "山寂寂兮无人，又苍苍兮多木。群龙兮满朝，",
            "君何为兮空谷。文寡和兮思深，道难知兮行独。",
            "悦石上兮流泉，与松间兮草屋。入云中兮养鸡，",
            "上山头兮抱犊。神与枣兮如瓜，虎卖杏兮收谷。",
            "愧不才兮妨贤，嫌既老兮贪禄。誓解印兮相从，",
            "何詹尹兮何卜。",
            "山中人兮欲归，云冥冥兮雨霏霏。水惊波兮翠菅蘼，",
            "白鹭忽兮翻飞，君不可兮褰衣。山万重兮一云，",
            "混天地兮不分。树晻暧兮氛氲，猿不见兮空闻。",
            "忽山西兮夕阳，见东皋兮远村。平芜绿兮千里，",
            "眇惆怅兮思君。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 126. 鱼山神女祠歌·迎神 ----------
    {
        "id": "wang-wei-126",
        "title": "鱼山神女祠歌·迎神",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷116》",
        "verse": [
            "坎坎击鼓，鱼山之下。吹洞箫，望极浦。女巫进，",
            "纷屡舞。陈瑶席，湛清酤。风凄凄兮夜雨，",
            "不知神之来兮不来，使我心兮苦复苦。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 127. 鱼山神女祠歌·送神 ----------
    {
        "id": "wang-wei-127",
        "title": "鱼山神女祠歌·送神",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷117》",
        "verse": [
            "纷进舞兮堂前，目眷眷兮琼筵。来不言兮意不传，",
            "作暮雨兮愁空山。悲急管兮思繁弦，神之驾兮俨欲旋。",
            "倏云收兮雨歇，山青青兮水潺湲。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 128. 白鼋涡（杂言走笔） ----------
    {
        "id": "wang-wei-128",
        "title": "白鼋涡（杂言走笔）",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷118》",
        "verse": [
            "南山之瀑水兮，激石滈瀑似雷惊，人相对兮不闻语声。",
            "翻涡跳沫兮苍苔湿，藓老且厚，春草为之不生。",
            "兽不敢惊动，鸟不敢飞鸣。白鼋涡涛戏濑兮，",
            "委身以纵横。王人之仁兮，不网不钓，得遂性以生成。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 129. 宋进马哀词 ----------
    {
        "id": "wang-wei-129",
        "title": "宋进马哀词",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷119》",
        "verse": [
            "背春涉夏兮，众木蔼以繁阴。连金华与玉堂兮，",
            "宫阁郁其沈沈。百官并入兮，何语笑之哑哑，",
            "君独静嘿以伤心。草王言兮不得辞，我悲减思兮少时。",
            "仆夫命驾兮，出阊阖，历通逵。陌上人兮如故，",
            "识不识兮往来。眼中不见兮吾儿，骖紫骝兮从青骊。",
            "低光垂彩兮，怳不知其所之。辟朱户兮望华轩，",
            "意斯子兮候门。忽思瘗兮城南，心瞀乱兮重昏。",
            "仰诉天之不仁兮，家唯一身，身止一子，何胤嗣之不繁，",
            "就单鲜而又死。将清白兮遗谁，问诗礼兮已矣。",
            "哀从中兮不可胜，岂暇料馀年兮复几。日黯黯兮颓晔，",
            "鸟翩翩兮疾飞。邈穷天兮不返，疑有日兮来归。",
            "静言思兮永绝，复惊叫兮沾衣。客有吊之者曰：",
            "观未始兮有物，同委蜕兮胡悲？且延陵兮未至，",
            "况西河兮不知。学无生兮庶可，幸能听于吾师。",
            "第一百二十六卷",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
