    # ---------- 188. 山居秋暝 ----------
    {
        "id": "wang-wei-188",
        "title": "山居秋暝",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "五言律诗",
        "year": "约开元末",
        "source": "《全唐诗·卷一二六》",
        "verse": [
            "空山新雨后，天气晚来秋。明月松间照，清泉石上流。",
            "竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。",
        ],
        "tijie": "此诗写终南山隐居秋日傍晚之景，诗中有画，画中有禅，为王维山水诗之代表作，苏轼谓「诗中有画，画中有诗」。",
        "notes": [
            ("暝", "日暮。"),
            ("空山", "幽静之山，非无人，谓心境空明。"),
            ("竹喧", "竹林中笑语声。"),
            ("浣女", "洗衣之女子。"),
            ("随意", "任凭。"),
            ("春芳歇", "春花凋谢。"),
            ("王孙", "原指贵族子弟，此王维自谓。"),
        ],
        "appreciation": "首联「空山新雨后，天气晚来秋」以清新笔调写秋山雨后之爽洁，「空」字已逗禅意。颔联「明月松间照，清泉石上流」一静（月照）一动（泉流），光影声色俱足，如一幅水墨：松间明月、石上清泉，明净如洗。颈联「竹喧归浣女，莲动下渔舟」以人活动破静境，浣女笑声、渔舟莲动，生活气息扑面而不扰其幽。尾联反用《楚辞·招隐士》「王孙兮归来」意，谓秋山足留，不必归去，隐逸之趣悠然。全诗动静相生，诗画禅三味交融。",
        "famous": [
            ("明月松间照，清泉石上流。", "诗画名句，明净如洗。"),
            ("竹喧归浣女，莲动下渔舟。", "以动写静名句。"),
        ],
        "sources": [
            "《全唐诗》卷一二六",
            "《唐诗鉴赏辞典》王维条（上海辞书出版社，1983）",
            "苏轼《书摩诘蓝田烟雨图》",
        ],
    },
