    # ---------- 194. 终南山 ----------
    {
        "id": "wang-wei-194",
        "title": "终南山",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "五言律诗",
        "year": "约开元末",
        "source": "《全唐诗·卷一二六》",
        "verse": [
            "太乙近天都，连山接海隅。白云回望合，青霭入看无。",
            "分野中峰变，阴晴众壑殊。欲投人处宿，隔水问樵夫。",
        ],
        "tijie": "此诗写终南山之雄伟辽阔，以远景与游踪写山势之变，为王维山水五律中之壮阔名篇。",
        "notes": [
            ("太乙", "终南山主峰。"),
            ("天都", "天帝所居，喻极高。"),
            ("海隅", "海角。"),
            ("青霭", "青色云气。"),
            ("分野", "星野分野，指地域。"),
            ("樵夫", "打柴人。"),
        ],
        "appreciation": "首联「太乙近天都，连山接海隅」以夸张写终南之高远：近天都、接海隅，气势宏观。颔联「白云回望合，青霭入看无」写山中之景：白云回望复合、青霭近看反无，捕捉山岚之变幻，空灵如画。颈联「分野中峰变，阴晴众壑殊」写中峰分野、众壑阴晴各异，见山势之广与变化之多。尾联「欲投人处宿，隔水问樵夫」以游踪收束，隔水问樵，闲远之趣悠然。王维此诗以阔笔写大山，与其小景之清幽异趣，转见壮伟。",
        "famous": [
            ("白云回望合，青霭入看无。", "写山名句，空灵变幻。"),
            ("分野中峰变，阴晴众壑殊。", "写山名句，广变多姿。"),
        ],
        "sources": [
            "《全唐诗》卷一二六",
            "《唐诗鉴赏辞典》王维条（上海辞书出版社，1983）",
        ],
    },
