    # ---------- 205. 使至塞上 ----------
    {
        "id": "wang-wei-205",
        "title": "使至塞上",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "五言律诗",
        "year": "开元二十五年（737）",
        "source": "《全唐诗·卷一二六》",
        "verse": [
            "单车欲问边，属国过居延。征蓬出汉塞，归雁入胡天。",
            "大漠孤烟直，长河落日圆。萧关逢候吏，都护在燕然。",
        ],
        "tijie": "此诗作于王维奉使凉州慰问将士途中。诗写塞外壮丽风光与使臣孤寂，其中「大漠孤烟直，长河落日圆」为千古写景名句。",
        "notes": [
            ("问边", "慰问边塞将士。"),
            ("属国", "典属国，此指使者身份。"),
            ("居延", "古边塞地名，今内蒙古额济纳。"),
            ("征蓬", "飘飞之蓬草，喻身世飘零。"),
            ("候骑", "侦察骑兵。"),
            ("都护", "边塞长官。"),
            ("燕然", "山名，窦宪勒铭处，此借指前线。"),
        ],
        "appreciation": "首联叙事，单车问边，过居延而远赴。颔联「征蓬出汉塞，归雁入胡天」以蓬草、归雁自况，写飘零远使之孤寂，景中含情。颈联「大漠孤烟直，长河落日圆」乃全诗警策：大漠无边，烽烟孤直；长河如带，落日浑圆。一「直」一「圆」，状难写之景如在目前，线条极简而意境极阔，王国维推为「千古壮观」之句。尾联写途中遇候骑，知都护在前，叙事收束，余韵悠然。",
        "famous": [
            ("大漠孤烟直，长河落日圆。", "写景名句，千古壮观。"),
        ],
        "sources": [
            "《全唐诗》卷一二六",
            "《唐诗鉴赏辞典》王维条（上海辞书出版社，1983）",
            "王国维《人间词话》",
        ],
    },
