    # ---------- 325. 相思 ----------
    {
        "id": "wang-wei-325",
        "title": "相思",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "五言绝句",
        "year": "约开元中",
        "source": "《全唐诗·卷一二八》",
        "verse": [
            "红豆生南国，秋来发故枝。愿君多采撷，此物最相思。",
        ],
        "tijie": "此诗一作《江上赠李龟年》，为王维怀念友人之作。红豆又名相思子，产于岭南，古人用以寄相思。诗借物寄情，语短情长。",
        "notes": [
            ("红豆", "一名相思子，产于岭南，实如豌豆，色红。"),
            ("南国", "南方，红豆产地。"),
            ("发几枝", "长出多少枝。"),
            ("采撷", "采摘。"),
            ("此物", "指红豆。"),
        ],
        "appreciation": "首句「红豆生南国」点物起兴，南国红豆天然含相思之意；次句「春来发几枝」以问句写春生之盛，暗寓相思之滋生。后二句「愿君多采撷，此物最相思」由物及人，嘱友多采红豆以寄相思——不直说己之相思，而劝人采撷，情意更婉转深长。全诗二十字，借寻常之物写至深之情，浑然天成，遂使「红豆」成为相思之代称，流传千古。",
        "famous": [
            ("愿君多采撷，此物最相思。", "相思名句，化为文化符号。"),
        ],
        "sources": [
            "《全唐诗》卷一二八",
            "《唐诗鉴赏辞典》王维条（上海辞书出版社，1983）",
        ],
    },
