    # ---------- 329. 田园乐七首（一作辋川六言，第六首一作皇甫曾诗） ----------
    {
        "id": "wang-wei-329",
        "title": "田园乐七首（一作辋川六言，第六首一作皇甫曾诗）",
        "author": "王维",
        "poet_id": "wang-wei",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷67》",
        "verse": [
            "厌见千门万户，经过北里南邻。",
            "官府鸣珂有底，崆峒散发何人。",
            "再见封侯万户，立谈赐璧一双。",
            "讵胜耦耕南亩，何如高卧东窗。",
            "采菱渡头风急，策杖林西日斜。",
            "杏树坛边渔父，桃花源里人家。",
            "萋萋春草秋绿，落落长松夏寒。",
            "牛羊自归村巷，童稚不识衣冠。",
            "山下孤烟远村，天边独树高原。",
            "一瓢颜回陋巷，五柳先生对门。",
            "桃红复含宿雨，柳绿更带朝烟。",
            "花落家童未扫，莺啼山客犹眠。",
            "酌酒会临泉水，抱琴好倚长松。",
            "南园露葵朝折，东谷黄粱夜舂。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
